#include <array>
#include <iostream>
#include <vector>
using namespace std;
struct State { array<int,4> child{}; bool terminal=false; };
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int tests; cin>>tests;
    while(tests--) {
        int m; cin>>m;
        vector<State> trie(2);  
        while(m--) {
            int n; cin>>n;
            vector<int> left(n+1),right(n+1);
            for(int i=1;i<=n;++i) cin>>left[i]>>right[i];
            auto leaf=[&](int u){return u && !left[u] && !right[u];};
            vector<pair<int,int>> pending{{1,1}};
            while(!pending.empty()) {
                auto [state,u]=pending.back(); pending.pop_back();
                if(leaf(u)) {trie[state].terminal=true;continue;}
                auto extend=[&](int direction,int v) {
                    if(!trie[state].child[direction]) {
                        int index=(int)trie.size();
                        trie[state].child[direction]=index;
                        trie.push_back(State{});
                    }
                    pending.push_back({trie[state].child[direction],v});
                };
                if(leaf(left[u]) && leaf(right[u])) {
                    extend(2,left[u]);extend(3,right[u]);continue;
                }
                if(!left[u]) extend(1,right[u]);
                if(!right[u]) extend(0,left[u]);
                if(right[u] && leaf(left[u])) extend(3,right[u]);
                if(left[u] && leaf(right[u])) extend(2,left[u]);
            }
        }
        vector<char> good(trie.size(),false);
        for(int u=(int)trie.size()-1;u>=1;--u) {
            good[u]=trie[u].terminal;
            if(!good[u]) {
                good[u]=true;
                for(int v:trie[u].child) if(!v || !good[v]) {good[u]=false;break;}
            }
        }
        cout<<(good[1]?"Almost Complete":"No")<<'\n';
    }
}
